#include <zephyr/ztest.h>
#include <zephyr/drivers/dac.h> 
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/dac/dac_emul.h>
#include <zephyr/device.h>

/* dac_test alias is defined in the overlay file */
#define DAC_NODE DT_ALIAS(dac_test)

static const struct device *const dac_dev = DEVICE_DT_GET(DAC_NODE);
static const struct emul *const dac_emul = EMUL_DT_GET(DAC_NODE);

static void *dac_emul_setup(void)
{
	zassert_true(device_is_ready(dac_dev), "DAC device is not ready");

	return NULL;
}

ZTEST(dac_emul, test_write_value)
{
	struct dac_channel_cfg cfg;
	uint32_t val;

	cfg.channel_id = 0;
	cfg.resolution = 12;
	zassert_ok(dac_channel_setup(dac_dev, &cfg), "Failed to setup channel");

	zassert_ok(dac_write_value(dac_dev, 0, 1234), "Failed to write value");
	zassert_ok(dac_emul_get_output(dac_emul, 0, &val), "Failed to get emulated output");
	zassert_equal(val, 1234, "Value mismatch, expected %%d, got %%d", 1234, val);

	/* Test max value */
	zassert_ok(dac_write_value(dac_dev, 0, 0xFFF), "Failed to write max value");
	zassert_ok(dac_emul_get_output(dac_emul, 0, &val), "Failed to get emulated output");
	zassert_equal(val, 0xFFF, "Max value mismatch, expected %%d, got %%d", 0xFFF, val);
}

ZTEST_SUITE(dac_emul, NULL, dac_emul_setup, NULL, NULL, NULL);
